-export function retrySchedule(options) {
-  return [];
+export function retrySchedule({ attempts, baseMs, factor, maxMs }) {
+  if (!Number.isInteger(attempts) || attempts < 1) {
+    throw new Error("invalid attempts: must be a positive integer");
+  }
+  if (!Number.isFinite(baseMs) || baseMs <= 0) {
+    throw new Error("invalid baseMs: must be a positive finite number");
+  }
+  if (!Number.isFinite(maxMs) || maxMs <= 0) {
+    throw new Error("invalid maxMs: must be a positive finite number");
+  }
+  if (baseMs > maxMs) {
+    throw new Error("invalid baseMs: must be <= maxMs");
+  }
+  if (!Number.isFinite(factor) || factor < 1) {
+    throw new Error("invalid factor: must be a finite number >= 1");
+  }
+
+  const delays = [];
+  for (let i = 0; i < attempts - 1; i++) {
+    delays.push(Math.min(baseMs * factor ** i, maxMs));
+  }
+  return delays;
 }
